probe(Array.isArray(slots.breaks) && slots.breaks.length > 0, "the counter must print its break");
probe(Array.isArray(slots.flights) && slots.flights.length > 0, "the case must print the two attempts");
const toMinutes = (text) => {
  const parts = text.split(":");
  return Number(parts[0]) * 60 + Number(parts[1]);
};
const from = toMinutes(slots.tickets[0].from);
const until = toMinutes(slots.tickets[0].until);
const breakFrom = toMinutes(slots.breaks[0].from);
const breakUntil = toMinutes(slots.breaks[0].until);
const flightFrom = toMinutes(slots.flights[0].from);
const flightUntil = toMinutes(slots.flights[1].from);
probe(flightFrom <= from && flightUntil <= until, "the first attempt must be the cheapest within the printed hours");
probe(breakFrom < from || breakUntil > until, "the break must extend beyond the printed opening-hours schedule");
