probe(typeof slots === "object" && slots !== null, "the case must carry the parsed journey");
probe(typeof slots.person === "string" && slots.person.length > 0, "the traveller must be named");
probe(typeof slots.destination === "string" && slots.destination.length > 0, "the destination must be named");
probe(Number.isInteger(slots.ticketsPerDay) && slots.ticketsPerDay > 0, "the counter must keep its tickets above zero");
probe(Number.isInteger(slots.counterHours) && slots.counterHours > 0, "the printed counter must cover at least one hour");
probe(slots.earliestFriday === true, "the hours must print the earliest Friday of the journey");
probe(slots.fromMonday === true, "the traveller must want the ticket from Monday");
probe(Array.isArray(slots.arrivalTimes) && slots.arrivalTimes.length === 2, "the hours must print the two arrival times");
probe(slots.arrivalTimes.every((arrival) => typeof arrival.day === "string" && arrival.day.length > 0), "both arrival times must name their day");
probe(slots.arrivalTimes.every((arrival) => Number.isInteger(arrival.time.hour) && arrival.time.hour >= 0 && arrival.time.hour < 24), "both arrival times must be printed before noon");
const hours = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const index = hours.indexOf(slots.destination);
probe(hours.includes(slots.destination), "the destination must be one of the weekdays");
const earlier = slots.arrivalTimes.find((arrival) => arrival.day === hours[index - 1]);
const later = slots.arrivalTimes.find((arrival) => arrival.day === slots.destination);
probe(earlier !== undefined, "the traveller must have an arrival time before the destination");
probe(later !== undefined, "the traveller must have an arrival time at or after the destination");
probe(earlier.time.hour < later.time.hour, "the earlier arrival time must be in the past");
probe(slots.counterHours * slots.ticketsPerDay - 30 > 0, "the last ticket window must open before it closes");
