const slots = $slots;
probe(typeof slots.place === "string" && slots.place.length > 0, "the case must name the place whose hours are printed");
probe(typeof slots.person === "string" && slots.person.length > 0, "the case must name the person who wants a ticket");
probe(Number.isInteger(slots.ticketsPerDay) && slots.ticketsPerDay > 0, "the counter must print a positive number of tickets per day");
probe(Number.isInteger(slots.availableTickets) && slots.availableTickets >= 0, "the last-availability must be a non-negative number");
probe(typeof slots.breakFrom === "string" && typeof slots.breakTo === "string", "the break must be printed as a time range");
probe(slots.firstRequest !== slots.secondRequest, "the two requested tickets must fall on different days");
const toMinutes = (time) => {
  const parts = time.split(":");
  return Number(parts[0]) * 60 + Number(parts[1]);
};
const from = toMinutes(slots.breakFrom);
const to = toMinutes(slots.breakTo);
probe(from <= to, "the break must be printed as a closed interval");
const available = slots.availableTickets - slots.ticketsPerDay;
const failed = (request) => {
  const parts = request.time.split(":");
  const minutes = Number(parts[0]) * 60 + Number(parts[1]);
  return minutes < from || minutes > to;
};
const attempts = [
  { label: slots.firstRequest.day, time: slots.firstRequest.time, failed: failed(slots.firstRequest) },
  { label: slots.secondRequest.day, time: slots.secondRequest.time, failed: failed(slots.secondRequest) }
];
const surviving = attempts.filter((attempt) => attempt.failed === false);
probe(surviving.length > 0, "at least one of the two requested tickets must arrive inside the break");
probe(surviving.length === 1, "the two requested tickets must arrive at different times within the break");
return "Try the " + surviving[0].day + " “" + surviving[0].time + "”.";

